INSERT INTO douleur_quiz_questions (douleur_id, question, options, correct_indices, sort_order) VALUES
  ((SELECT id FROM douleurs WHERE slug = 'amour-propre'), 'L''amour propre, selon ce protocole, est :', '["La base de ce que tu acceptes, ressens et construis", "Un luxe réservé à certains", "Une question de réussite sociale", "Un trait de caractère figé"]'::jsonb, '[0]'::jsonb, 1),
