  ((SELECT id FROM douleurs WHERE slug = 'amour-propre'), '« Ici, tu ne cherches pas à te ___ »', '["Reposer", "Dépasser", "Protéger", "Convaincre"]'::jsonb, '[3]'::jsonb, 12),
  ((SELECT id FROM douleurs WHERE slug = 'amour-propre'), 'L''étape « Agir » se déroule sur :', '["21 jours", "3 jours", "7 jours", "1 an"]'::jsonb, '[0]'::jsonb, 13),
